<section class="inventory-dashboard"><div class="inventory-head"><div><p class="inventory-kicker">BOUTIQUE · TEMPS RÉEL</p><h2>Pilotage du stock</h2><p>Les ventes diminuent le stock automatiquement et les annulations le rétablissent.</p></div><a class="btn primary" href="/admin/produits">Gérer le stock →</a></div><div class="inventory-metrics"><article><small>UNITÉS DISPONIBLES</small><strong><?= number_format($inventory['units'],0,',',' ') ?></strong><span>Stock physique total</span></article><article><small>VALEUR DU STOCK</small><strong><?= number_format($inventory['value'],0,',',' ') ?> F</strong><span>Au prix de vente actuel</span></article><article class="<?= $inventory['low']?'warning':'' ?>"><small>STOCK FAIBLE</small><strong><?= (int)$inventory['low'] ?></strong><span>Produit(s) sous le seuil</span></article><article class="<?= $inventory['out']?'danger':'' ?>"><small>RUPTURES</small><strong><?= (int)$inventory['out'] ?></strong><span>Réapprovisionnement requis</span></article></div><div class="inventory-grid"><div class="inventory-list"><div class="inventory-title"><h3>Niveaux de stock</h3><a href="/admin/produits">Voir tout</a></div><?php foreach($stockProducts as $product): $ratio=$product['low_stock_threshold']>0?min(100,(int)round($product['stock_quantity']/max(1,$product['low_stock_threshold']*2)*100)):100; ?><article><div class="inventory-product"><?php if($product['image']): ?><img src="<?= htmlspecialchars($product['image']) ?>" alt=""><?php else: ?><span>IF</span><?php endif ?><div><strong><?= htmlspecialchars($product['name']) ?></strong><small><?= htmlspecialchars($product['reference']) ?></small></div></div><div class="inventory-level"><b class="<?= (int)$product['stock_quantity']===0?'danger-text':((int)$product['stock_quantity']<=(int)$product['low_stock_threshold']?'warning-text':'') ?>"><?= (int)$product['stock_quantity'] ?> unité(s)</b><div><i style="width:<?= $ratio ?>%"></i></div><small>Seuil : <?= (int)$product['low_stock_threshold'] ?></small></div></article><?php endforeach ?></div><div class="movement-feed"><div class="inventory-title"><h3>Mouvements récents</h3></div><?php if(!$movements): ?><p class="inventory-none">Aucun mouvement enregistré.</p><?php endif ?><?php foreach($movements as $movement): ?><article><span class="movement-icon <?= (int)$movement['quantity']>=0?'up':'down' ?>"><?= (int)$movement['quantity']>=0?'↗':'↘' ?></span><div><strong><?= htmlspecialchars($movement['product_name']) ?></strong><small><?= htmlspecialchars($movement['note']??'Mouvement de stock') ?> · <?= date('d/m H:i',strtotime($movement['created_at'])) ?></small></div><b><?= (int)$movement['quantity']>=0?'+':'' ?><?= (int)$movement['quantity'] ?></b></article><?php endforeach ?></div></div></section>
