tory-product small,.inventory-level small,.movement-feed small{font-size:8px;color:#89909d}.inventory-level{width:130px;text-align:right;align-items:flex-end}.inventory-level b{font-size:9px}.inventory-level>div{height:4px;width:100%;border-radius:5px;background:#eceef2;margin:5px 0;overflow:hidden}.inventory-level i{display:block;height:100%;background:#28a673;border-radius:5px}.warning-text{color:#d08018}.danger-text{color:#d84949}.movement-feed>article{justify-content:flex-start;gap:9px}.movement-feed>article>div{display:flex;flex:1;flex-direction:column}.movement-feed>article>b{font-size:10px}.movement-icon{width:29px;height:29px;border-radius:9px;display:grid;place-items:center}.movement-icon.up{background:#e6f7ef;color:#16865b}.movement-icon.down{background:#fdeaea;color:#c44848}.inventory-none{color:#8b92a0;font-size:10px;margin:20px 0 5px}@media(max-width:900px){.inventory-metrics{grid-template-columns:1fr 1fr}.inventory-grid{grid-template-columns:1fr}}@media(max-width:520px){.inventory-head{align-items:flex-start;gap:15px}.inventory-head .btn{font-size:9px}.inventory-metrics{grid-template-columns:1fr 1fr}.inventory-list>article{align-items:flex-start;gap:10px}.inventory-level{width:95px}}</style>
